const HIDDEN_LINK_TRACKS = new Set<string>();
const SEARCH_LESSON_PREFIXES = new Set(['a1', 'a1-v1', 'a2']);
const normalizeId = (id: string) => id.replace(/\.mdx?$/, '').replace(/\/index$/, '');
const hrefFromRoute = (route: string) => `/${route}/`;
const trackIds = Object.keys(TRACKS);
const searchTrackIds = trackIds.filter((id) => !HIDDEN_LINK_TRACKS.has(id));

const allDocs = await getCollection('docs');
// Хрестоматія readings — surfaced in site-wide search like Word Atlas entries.
const allReadings = (await getCollection('readings')).filter(isPublishedReading);
const visibleDocs = allDocs.filter((entry) => {
  const id = normalizeId(entry.id);
  const track = id.split('/')[0];
  if (HIDDEN_DOCS.has(id)) return false;
  if (entry.data.draft && import.meta.env.PROD) return false;
  return track in TRACKS || (id !== 'index' && id === track);
});

const deployedDocsByTrack = new Map<string, DocsEntry[]>();
const landingDocsByTrack = new Map<string, DocsEntry>();
for (const entry of visibleDocs) {
  const id = normalizeId(entry.id);
  const track = id.split('/')[0];
  if (id === track) {
    landingDocsByTrack.set(track, entry);
    continue;
  }
  const bucket = deployedDocsByTrack.get(track) ?? [];
  bucket.push(entry);
  deployedDocsByTrack.set(track, bucket);
}
for (const entries of deployedDocsByTrack.values()) {
  entries.sort((a, b) => (a.data.sidebar?.order ?? 999) - (b.data.sidebar?.order ?? 999));
}

const searchItems: SearchItem[] = [
  ...searchTrackIds.map((id) => {
    navLabel: 'Уроки цього рівня',
    progressDone: position,
    progressTotal: links.length,
    links,
  };
})();

const plannedModuleGroups = (track: string, trackOverview: TrackOverview) => {
  const count = moduleCount(track);
  return [{
    unit: `${trackOverview.label} planned modules`,
    items: Array.from({ length: count }, (_, index) => {
      const num = index + 1;
      return {
        num,
        slug: `planned-${String(num).padStart(2, '0')}`,
        title: `Planned module ${String(num).padStart(2, '0')}`,
        sub: 'Mapped curriculum slot; not released for study yet.',
        status: 'locked' as const,
      };
    }),
  }];
};
