const currentTrackId = props.kind === 'track' ? props.track : docTrack;
const navItems = HIDDEN_LINK_TRACKS.has(currentTrackId)
  ? [{ href: '/', label: 'Home' }]
  : props.kind === 'doc'
  ? [
      { href: '/', label: 'Home' },
      { href: `/${docTrack}/`, label: TRACKS[docTrack]?.label ?? docTrack.toUpperCase() },
      { href: hrefFromRoute(docRoute), label: props.entry.data.sidebar?.label ?? props.entry.data.title },
    ]
  : props.kind === 'landingDoc'
    ? [
        { href: '/', label: 'Home' },
        { href: hrefFromRoute(docRoute), label: TRACKS[docTrack]?.label ?? props.entry.data.title },
      ]
  : [
      { href: '/', label: 'Home' },
      { href: pageMeta.currentPath, label: pageMeta.title },
    ];

// A1 lessons live under a module (`a1/<module>/<n>`); the module page lists them
// and lesson pages get a sidebar of their siblings. Other tracks keep the flat
// per-track lesson list (#2823).
const sidebar = (() => {
  const trackId = props.kind === 'track' ? props.track : docTrack;
  if (!trackId || HIDDEN_LINK_TRACKS.has(trackId)) return undefined;
  const trackDocs = deployedDocsByTrack.get(trackId) ?? [];

  if (trackId === 'a1') {
    if (props.kind !== 'doc') return undefined;
    const moduleSlug = docRoute.split('/')[1];
    if (!moduleSlug) return undefined;
    const lessons = trackDocs
      .map((entry) => ({ entry, route: lessonRoute(entry.id, 'a1') }))
      .filter(({ route }) => route?.module === moduleSlug)
      .sort((a, b) => a.route!.n - b.route!.n);
    if (lessons.length === 0) return undefined;
    const links = lessons.map(({ entry, route }) => {
      const id = normalizeId(entry.id);
      return {
        href: hrefFromRoute(id),
        label: entry.data.title,
        num: String(route!.n).padStart(2, '0'),
        active: id === docRoute,
      };
    });
    const currentIndex = links.findIndex((link) => link.active);
    const position = currentIndex >= 0 ? currentIndex + 1 : 0;
    const count = formatLessonCount(links.length);
    return {
      backHref: '/a1/',
      backLabel: TRACKS.a1?.label ?? 'A1',
      positionLabel: position > 0 ? `Урок ${position} з ${links.length}` : count.uk,
      positionLabelEn: position > 0 ? `Lesson ${position} of ${links.length}` : count.en,
      titleLabel: 'Уроки',
      navLabel: 'Уроки цього модуля',
      progressDone: position,
      progressTotal: links.length,
      links,
    };
  }

  if (props.kind !== 'doc') return undefined;
  const lessons = trackDocs;
  if (lessons.length === 0) return undefined;
  const links = lessons.map((entry) => {
    const id = normalizeId(entry.id);
    const order = entry.data.sidebar?.order;
    return {
      href: hrefFromRoute(id),
      label: entry.data.title,
      num: order ? String(order).padStart(2, '0') : '•',
      active: id === docRoute,
    };
  });
  const currentIndex = links.findIndex((link) => link.active);
  const position = currentIndex >= 0 ? currentIndex + 1 : 0;
  return {
    backHref: `/${trackId}/`,
    backLabel: TRACKS[trackId]?.label ?? trackId.toUpperCase(),
    positionLabel: position > 0 ? `Урок ${position} з ${links.length}` : formatLessonCount(links.length).uk,
    positionLabelEn: position > 0 ? `Lesson ${position} of ${links.length}` : formatLessonCount(links.length).en,
    titleLabel: 'Уроки',
    navLabel: 'Уроки цього рівня',
    progressDone: position,
    progressTotal: links.length,
    links,
  };
})();

